# Adaptadores de idioma: la biblioteca original permanece intacta.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  say "$TOTAL_STAGES pasos"
  say "Tú manejas el navegador; esta guía te indica qué hacer."
  say "Puedes detenerla con Ctrl-C y volver a ejecutarla."
  pause "Pulsa Intro para empezar."
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Paso %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Pulsa Intro para continuar}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s¿%s? [s/N] %s' "$YELLOW" "$1" "$RESET"
  read -r reply || true
  [[ "$reply" =~ ^[SsYy] ]]
}

open_url() {
  local url="$1"
  say "Abriendo: $url"
  { if command -v wslview >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "No se pudo abrir el navegador. Abre esta URL manualmente: $url"
}

finish() {
  _clear
  printf '\n%s%s  ✓ Guía completada%s\n\n' "$BOLD" "$GREEN" "$RESET"
}

run_wizard() {
  # One-off prototype setup. No .env writes, new secrets, production changes,
  # automatic issue closure, or automatic deletion of vendor data.
  cd "$(dirname "${BASH_SOURCE[0]}")/.."
  TOTAL_STAGES=7
  banner "Knock Development: configuración y comprobaciones"

  stage "Confirmar Development y los requisitos locales"
  say "Configurarás dos workflows de prueba y el valor predeterminado de una categoría."
  say "Después enviaremos notificaciones al feed y crearemos un destinatario solo en Knock."
  say "No se escriben credenciales ni se modifica SQLite. Ctrl-C detiene la guía."
  [[ -t 0 ]] || { warn "Ejecuta la guía de forma interactiva en una terminal."; return 1; }
  command -v node >/dev/null || { warn "Necesitas Node.js."; return 1; }
  [[ -f "$ENV_FILE" ]] || { warn "Falta $ENV_FILE; utiliza las claves locales de desarrollo existentes."; return 1; }
  knock_probe preflight
  open_url "https://dashboard.knock.app"
  step "Selecciona la cuenta de Cadence y el entorno Development."
  step "Usa la rama predeterminada/main de Knock que utiliza la app, no una rama de funcionalidad."
  warn "Si la interfaz no coincide con estas rutas documentadas, detente y pregunta."
  confirm "Está seleccionado Development y no modificarás Production" || return 1

  stage "Crear el workflow de Discussion Reply"
  open_url "https://dashboard.knock.app"
  step "Abre Workflows y crea un workflow, o abre el prototipo si ya existe."
  say "Nombre: Cadence prototype Discussion Reply"
  say "Key exacta: cadence-prototype-discussion-reply"
  step "Añade UN paso In-app feed con el canal Cadence feed existente."
  say "El UUID del canal mostrado al inicio debe coincidir con el que usa la app."
  step 'Configura el cuerpo del mensaje con: {{ data.message }}'
  step "Entrega inmediata: sin batch, delay, condiciones ni límite de una vez por destinatario."
  step "No añadas pasos de email, push, SMS ni otros canales."
  step "NO añadas la categoría de Enrollment a este workflow de Discussion Reply."
  step "Guarda y haz Commit de ESTE workflow en Development. Guardar el borrador no basta."
  note "Haz Commit desde su página; evita Commit all si hay borradores ajenos a esta prueba."
  note "No promociones ni publiques nada en Production."
  confirm "El workflow de Discussion Reply está Active y tiene Commit en Development" || return 1

  stage "Crear el workflow y la categoría de Enrollment"
  open_url "https://dashboard.knock.app"
  step "En Workflows, crea o abre el prototipo de Enrollment."
  say "Nombre: Cadence prototype new Enrollment"
  say "Key exacta: cadence-prototype-enrollment"
  step "Añade UN paso inmediato de Cadence feed, igual que en Discussion Reply."
  step 'Configura el cuerpo del mensaje con: {{ data.message }}'
  step 'Página del workflow → "..." → "Manage workflow": añade esta categoría exacta:'
  say "cadence-prototype-enrollment"
  step 'Deja desactivada la opción "Override recipient preferences".'
  step "No añadas otras categorías, condiciones, delays, batches ni límites de frecuencia."
  step "Mantén el workflow Active. Guarda y haz Commit en Development."
  note "Documentación: https://docs.knock.app/concepts/workflows#workflow-categories"
  confirm "El workflow y su categoría tienen Commit y respetan las preferencias" || return 1

  stage "Desactivar Enrollment por defecto en Development"
  open_url "https://dashboard.knock.app/~/preferences"
  step "Comprueba que sigues en Development. Ve a Platform → Preferences → valores predeterminados del entorno."
  step "Conserva la configuración existente; añade solo esta categoría del prototipo."
  say 'Dentro de categories, añade esta entrada (NO pongas toda la categoría a false):'
  cat <<'JSON'
  "cadence-prototype-enrollment": {
    "channel_types": {
      "in_app_feed": false,
      "email": false
    }
  }
JSON
  say "Si ves interruptores en lugar de JSON, desactiva ambos tipos de canal"
  say "para esta categoría, sin cambiar los demás valores predeterminados."
  warn "Estos valores se aplican inmediatamente: NO requieren Commit ni promoción."
  confirm "Solo cambiarás la categoría del prototipo en Development; listo para guardar" || return 1
  step "Guarda las preferencias predeterminadas del entorno en el panel."
  note "Documentación: https://docs.knock.app/preferences/custom-preference-center"
  confirm "Has guardado en Development conservando los demás valores" || return 1

  stage "Comprobación 2: enviar una notificación de Discussion Reply"
  say "Ejecuta en otra terminal: npm run dev"
  say "Deja el servidor en marcha. Esta guía no lo inicia ni lo detiene."
  ask APP_ORIGIN "URL de la app indicada por el servidor (p. ej. http://localhost:5173):"
  APP_ORIGIN="${APP_ORIGIN%/}"
  [[ "$APP_ORIGIN" =~ ^http://(localhost|127\.0\.0\.1)(:[0-9]+)?$ ]] || {
    warn "Utiliza una URL de desarrollo http://localhost o http://127.0.0.1."; return 1;
  }
  open_url "$APP_ORIGIN"
  step "Selecciona a Sarah Chen (Instructor) en DevUI."
  pause "Pulsa Intro cuando hayas seleccionado a una persona en la sesión."
  open_url "$APP_ORIGIN/prototype/knock"
  step "En Simulate a Discussion Reply, elige una Discussion Question de Emma Wilson"
  say "(persona 5) y pulsa Send Notification UNA sola vez."
  step "Comprueba que el resultado nombra a Emma e incluye workflow_run_id, no un error."
  step "Cambia a Emma Wilson mediante DevUI. Pulsa List + counts."
  step "La entrega es asíncrona: vuelve a consultar hasta ver el question_id correspondiente."
  say "Aceptar el envío NO demuestra por sí solo que se haya entregado."
  say "Si aparece workflow_missing: comprueba la key exacta y haz Commit en Development."
  say "Si no llega: revisa el motivo en Observability → Runs de Knock."
  confirm "Aparece en el feed de Emma la notificación de Discussion Reply correspondiente" || return 1

  stage "Comprobación 3: listado, contadores, visto, leído y aislamiento"
  step "Como Emma, pulsa List + counts. Anota el id del primer elemento, unread_count y unseen_count."
  step "Pulsa Mark first seen y después List + counts."
  step "Comprueba que ese mismo elemento tiene seen_at y unseen_count baja en uno"
  say "(si antes no estaba visto). El estado de lectura debe mantenerse."
  step "Pulsa Mark first read y después List + counts."
  step "Comprueba read_at del mismo elemento y unread_count (uno menos si antes no estaba leído)."
  step "Recarga y consulta otra vez: las fechas y los contadores deben mantenerse."
  step "Cambia a otro Student mediante DevUI. Consulta: el id de la notificación de Emma no debe aparecer."
  step "Vuelve a Emma y consulta: su notificación debe seguir ahí."
  note "Si cambia el primer elemento, compara los ids para no confundir sus estados."
  confirm "Funcionan el listado, los contadores, la persistencia de visto/leído y el aislamiento" || return 1

  stage "Comprobación 4: desactivado por defecto y activación solo del feed"
  say "La página permite editar preferencias, pero no enviar eventos de Enrollment."
  say "Este paso utiliza el SDK de Node y llamadas firmadas con la clave pública."
  say "Creará un destinatario nuevo que representa a un Instructor solo en Knock,"
  say "sin email ni registro en SQLite. Quedará en Development para inspeccionarlo."
  confirm "Crear el destinatario y enviar un Enrollment antes de activar las notificaciones" || return 1
  PROBE_ID="cadence-prototype-instructor-$(node -e 'console.log(crypto.randomUUID())')"
  export PROBE_ID
  knock_probe before
  open_url "https://dashboard.knock.app/~/runs"
  step "En Development, busca la ejecución de Enrollment con el id de destinatario/ejecución mostrado."
  step "Espera a que termine e inspecciona el paso in-app en el depurador."
  step "Debe omitirse específicamente por las preferencias, NO por un error,"
  say "datos o canal ausentes, workflow inactivo o ejecución incompleta."
  confirm "La ejecución terminó y omitió el envío por las preferencias" || return 1
  knock_probe verify-before
  confirm "Activar solo el feed para este destinatario y enviar otro Enrollment" || return 1
  knock_probe after
  step "Inspecciona la nueva ejecución de Enrollment en el mismo depurador y espera a que termine."
  step "Debe generar un mensaje en el feed de este destinatario."
  confirm "La ejecución posterior a la activación terminó y generó un mensaje en el feed" || return 1
  knock_probe verify-after
  say "Ahora comprueba los controles de la app con un Instructor real:"
  open_url "$APP_ORIGIN/prototype/knock"
  step "Selecciona un Instructor en DevUI y pulsa Read preferences."
  step "Pulsa Initialize off y después Read preferences. En la categoría del prototipo,"
  say "in_app_feed y email deben tener el valor false."
  step "Pulsa Opt into feed only y luego Read preferences: in_app_feed=true, email=false."
  step "Recarga y vuelve a consultar para comprobar la persistencia."
  note "No hay proveedor de email configurado: esto comprueba el valor de la preferencia,"
  note "no la entrega ni el bloqueo real de correos."
  confirm "Los valores de preferencias por categoría y canal persisten en la app" || return 1

  finish
  say "Comprobaciones guiadas completadas; esto no resuelve automáticamente la decisión."
  say "Comparte tus observaciones y los ids de las dos ejecuciones de Enrollment en nuestra conversación."
  say "El destinatario de prueba permanece en Development: $PROBE_ID"
  say "No se han escrito credenciales ni se ha modificado Production."
  say "Al repetir la guía se crea otro destinatario; no se eliminan las pruebas anteriores."
}

# Only runs when the human reaches the relevant wizard stage.
# Uses existing development credentials without sourcing .env as shell code.
knock_probe() {
  node --env-file="$ENV_FILE" --input-type=module - "$1" <<'NODE'
import { Knock, signUserToken } from "@knocklabs/node";
const operation = process.argv[2];
const env = process.env;
for (const key of ["KNOCK_SECRET_API_KEY", "KNOCK_PUBLIC_API_KEY", "KNOCK_SIGNING_KEY", "KNOCK_FEED_CHANNEL_ID"]) {
  if (!env[key]) throw new Error(`Falta ${key} en el entorno/.env`);
}
if (!env.KNOCK_SECRET_API_KEY.startsWith("sk_test_") ||
    !env.KNOCK_PUBLIC_API_KEY.startsWith("pk_test_")) {
  throw new Error("Por seguridad, solo se admiten claves de desarrollo.");
}
if (operation === "preflight") {
  console.log("  Prefijos de claves de Development comprobados. UUID de Cadence feed:", env.KNOCK_FEED_CHANNEL_ID);
  process.exit(0);
}
const id = env.PROBE_ID;
if (!id?.startsWith("cadence-prototype-instructor-")) throw new Error("Falta el id del destinatario de prueba");
const knock = new Knock({ apiKey: env.KNOCK_SECRET_API_KEY });
const category = "cadence-prototype-enrollment";
async function signedGet(path) {
  const response = await fetch(`https://api.knock.app/v1/users/${encodeURIComponent(id)}/${path}`, {
    headers: {
      Authorization: `Bearer ${env.KNOCK_PUBLIC_API_KEY}`,
      "X-Knock-User-Token": await signUserToken(id, { expiresInSeconds: 300 }),
    },
  });
  if (!response.ok) throw new Error(`Falló la petición firmada a ${path}: HTTP ${response.status}`);
  return response.json();
}
async function preferences(expected) {
  const prefs = await signedGet("preferences/default");
  const channels = prefs.categories?.[category]?.channel_types;
  console.log("  Preferencias de la categoría:", JSON.stringify(channels));
  if (channels?.in_app_feed !== expected || channels?.email !== false) {
    throw new Error("Preferencias inesperadas. Revisa los valores predeterminados y la categoría en Development antes de continuar.");
  }
}
try {
  console.log("  Destinatario de prueba:", id);
  if (operation === "before") {
    await knock.users.update(id, { name: "PROTOTIPO Instructor — activación de Enrollment", role: "instructor" });
    // Deliberately do not set recipient preferences: test the actual environment default.
    await preferences(false);
  } else if (operation === "after") {
    await knock.users.setPreferences(id, "default", {
      __persistence_strategy__: "merge",
      categories: { [category]: { channel_types: { in_app_feed: true, email: false } } },
    });
    await preferences(true);
  }
  if (operation === "before" || operation === "after") {
    const result = await knock.workflows.trigger(category, {
      recipients: [id],
      data: {
        message: `PROTOTIPO: nuevo Enrollment (${operation === "before" ? "antes" : "después"} de activar las notificaciones)`,
        probe_id: id,
        probe_phase: operation,
      },
    });
    console.log(`  Ejecución ${operation === "before" ? "antes" : "después"} de activar las notificaciones:`, result.workflow_run_id);
    console.log("  Ejecución asíncrona aceptada; inspecciónala una vez terminada antes de continuar.");
  } else if (operation === "verify-before" || operation === "verify-after") {
    const feed = await signedGet(`feeds/${env.KNOCK_FEED_CHANNEL_ID}`);
    const entries = (feed.entries ?? []).filter(item => item.data?.probe_id === id);
    console.log("  Estado del feed:", JSON.stringify({ meta: feed.meta, entries }, null, 2));
    if (entries.some(item => item.data?.probe_phase === "before")) {
      throw new Error("Enrollment entregado antes de activar las notificaciones: comprobación de preferencias FALLIDA.");
    }
    if (operation === "verify-after" && !entries.some(item => item.data?.probe_phase === "after")) {
      throw new Error("No aparece la notificación posterior a la activación. Inspecciona la ejecución y repite la comprobación; no la des por superada.");
    }
  } else {
    throw new Error("Operación de prueba desconocida");
  }
} catch (error) {
  console.error("  Comprobación detenida:", error.message);
  process.exitCode = 1;
}
NODE
}

run_wizard "$@"; exit
